    console.log('Wrote CSV: ' + paths.csvPath);
    console.log('Wrote attempts CSV: ' + paths.attemptsCsvPath);
    console.log('Wrote JSON: ' + paths.jsonPath);
    console.log('Wrote HTML: ' + paths.htmlPath);
