        attemptsCsvPath: firstDefined(custom.attemptsCsvPath, outputDir + '/ai_teammate_token_usage_attempts.csv'),
        jsonPath: firstDefined(custom.jsonPath, outputDir + '/ai_teammate_token_usage.json'),
